export { default as PromptInput } from "./PromptInput.vue";
export { default as PromptInputAttach } from "./PromptInputAttach.vue";
export { default as PromptInputAttachment } from "./PromptInputAttachment.vue";
export { default as PromptInputAttachments } from "./PromptInputAttachments.vue";
export { default as PromptInputSubmit } from "./PromptInputSubmit.vue";
export { default as PromptInputTextarea } from "./PromptInputTextarea.vue";
export { default as PromptInputToolbar } from "./PromptInputToolbar.vue";
export { usePromptInput } from "./utils";
export type { PromptInputContext, PromptInputMessage } from "./utils";

import type { ComputedRef, InjectionKey, Ref } from "vue";
import { inject } from "vue";

export interface PromptInputMessage {
  text: string;
  files: File[];
}

export interface PromptInputContext {
  text: Ref<string>;
  files: Ref<File[]>;
  pending: ComputedRef<boolean>;
  canSubmit: ComputedRef<boolean>;
  submit: () => void;
  stop: () => void;
  textarea: () => HTMLTextAreaElement | null;
}

export const promptInputKey: InjectionKey<PromptInputContext> = Symbol("prompt-input");

export function usePromptInput(): PromptInputContext {
  const context = inject(promptInputKey);
  if (!context) throw new Error("usePromptInput() must be called inside <PromptInput>.");
  return context;
}
